// Local attachment repository. Only metadata is stored in the main JSON database.
let database;
function openDB(){return database??=new Promise((resolve,reject)=>{const request=indexedDB.open('science-lab-files',1);request.onupgradeneeded=()=>request.result.createObjectStore('files');request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error);});}
export async function putFile(file,id){const db=await openDB();return new Promise((resolve,reject)=>{const tx=db.transaction('files','readwrite');tx.objectStore('files').put(file,id);tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error);});}
export async function getFile(id){const db=await openDB();return new Promise((resolve,reject)=>{const req=db.transaction('files').objectStore('files').get(id);req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
export async function getAllFiles(){const db=await openDB();return new Promise((resolve,reject)=>{const tx=db.transaction('files');const store=tx.objectStore('files');const keys=store.getAllKeys(),values=store.getAll();tx.oncomplete=()=>resolve(keys.result.map((id,i)=>({id,file:values.result[i]})));tx.onerror=()=>reject(tx.error);});}
export async function clearFiles(){const db=await openDB();return new Promise((resolve,reject)=>{const tx=db.transaction('files','readwrite');tx.objectStore('files').clear();tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});}
export async function passwordHash(password,salt){const raw=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveBits']);const bits=await crypto.subtle.deriveBits({name:'PBKDF2',salt:new TextEncoder().encode(salt),iterations:150000,hash:'SHA-256'},raw,256);return [...new Uint8Array(bits)].map(b=>b.toString(16).padStart(2,'0')).join('');}
